import json,os,subprocess
from pathlib import Path
root=Path("/srv/projects/android-sdk")
out={"mode":"read_only","path":str(root),"exists":root.is_dir(),"is_symlink":root.is_symlink()}
if root.is_dir():
 p=subprocess.run(["/usr/bin/du","-x","-B1","-d","2",str(root)],capture_output=True,text=True,timeout=85)
 sizes=[]
 for line in p.stdout.splitlines():
  try:
   v,k=line.split("\t",1)
   sizes.append({"path":k,"bytes":int(v)})
  except ValueError:pass
 out["directory_sizes"]=sorted(sizes,key=lambda x:-x["bytes"])[:35]
 out["root_entries"]=[{"name":x.name,"symlink":x.is_symlink(),"target":os.readlink(x) if x.is_symlink() else None} for x in root.iterdir()][:30]
 out["sdk_marker_files"]={s:(root/s).exists() for s in ("sdkmanager","cmdline-tools","platforms","platform-tools","build-tools","state/root-android","cache/root-gradle")}
for k in ("/opt/android-sdk","/root/Android/Sdk","/home/ubuntu/Android/Sdk"):
 p=Path(k)
 out[k]={"exists":p.exists(),"symlink":p.is_symlink(),"target":os.readlink(p) if p.is_symlink() else None}
print(json.dumps(out,ensure_ascii=True,sort_keys=True))
